#!/usr/bin/env node

'use strict';

// Capture a screenshot from a running Android emulator into
// .locofy/context/<name>.png.
//
// Exit codes: 0 = captured · 1 = no booted device · 3 = setup/capture error
//
// Usage:
//   node capture-screenshot.cjs --name <screen> [--project-dir DIR]

var childProcess = require('child_process');
var fs = require('fs');
var os = require('os');
var path = require('path');

function isFile(file) {
  try {
    return fs.statSync(file).isFile();
  } catch (_error) {
    return false;
  }
}

function platformExecutable(name, platform) {
  return platform === 'win32' ? name + '.exe' : name;
}

function decodeLocalPropertiesPath(value) {
  return value.trim().replace(/\\:/g, ':').replace(/\\\\/g, '\\').replace(/\\ /g, ' ');
}

function sdkRoots(projectDirectory, environment, platform, homeDirectory) {
  var roots = [];

  function add(value) {
    if (!value) {
      return;
    }
    var resolved = path.resolve(value);
    if (roots.indexOf(resolved) === -1) {
      roots.push(resolved);
    }
  }

  add(environment.ANDROID_HOME);
  add(environment.ANDROID_SDK_ROOT);

  var localProperties = path.join(projectDirectory, 'local.properties');
  if (isFile(localProperties)) {
    var match = fs.readFileSync(localProperties, 'utf8').match(/^sdk\.dir=(.*)$/m);
    if (match) {
      add(decodeLocalPropertiesPath(match[1]));
    }
  }

  if (platform === 'darwin') {
    add(path.join(homeDirectory, 'Library', 'Android', 'sdk'));
  } else if (platform === 'win32') {
    add(
      environment.LOCALAPPDATA
        ? path.join(environment.LOCALAPPDATA, 'Android', 'Sdk')
        : path.join(homeDirectory, 'AppData', 'Local', 'Android', 'Sdk'),
    );
  } else {
    add(path.join(homeDirectory, 'Android', 'Sdk'));
  }
  return roots;
}

function findOnPath(name, environment, platform) {
  var executableNames = [platformExecutable(name, platform)];
  var pathValue = environment.PATH || environment.Path || '';
  var separator = platform === 'win32' ? ';' : ':';
  var directories = pathValue.split(separator).filter(Boolean);
  if (platform === 'win32') {
    executableNames = (environment.PATHEXT || '.EXE;.CMD;.BAT;.COM')
      .split(';')
      .filter(Boolean)
      .map(function (extension) {
        return name + extension.toLowerCase();
      });
  }

  for (var directoryIndex = 0; directoryIndex < directories.length; directoryIndex += 1) {
    for (var nameIndex = 0; nameIndex < executableNames.length; nameIndex += 1) {
      var candidate = path.join(directories[directoryIndex], executableNames[nameIndex]);
      if (isFile(candidate)) {
        return candidate;
      }
    }
  }
  return '';
}

function resolveAdb(projectDirectory, environment, platform, homeDirectory) {
  var roots = sdkRoots(projectDirectory, environment, platform, homeDirectory);
  for (var index = 0; index < roots.length; index += 1) {
    var candidate = path.join(roots[index], 'platform-tools', platformExecutable('adb', platform));
    if (isFile(candidate)) {
      return candidate;
    }
  }
  return findOnPath('adb', environment, platform);
}

function emulatorSerials(output) {
  return String(output || '')
    .split(/\r?\n/)
    .map(function (line) {
      var match = line.match(/^(emulator-\d+)\s+device(?:\s|$)/);
      return match ? match[1] : '';
    })
    .filter(Boolean);
}

function preferredEmulatorSerial(session, runningSerials) {
  return session &&
    typeof session.serial === 'string' &&
    runningSerials.indexOf(session.serial) !== -1
    ? session.serial
    : runningSerials[0] || '';
}

function sanitizeName(name) {
  var safe = String(name || 'screenshot')
    .replace(/[ /:]/g, '_')
    .replace(/[^A-Za-z0-9_-]/g, '');
  return safe || 'screenshot';
}

function parseArguments(args) {
  var options = {
    projectDirectory: process.cwd(),
    name: '',
  };
  for (var index = 0; index < args.length; index += 1) {
    var argument = args[index];
    if (argument !== '--project-dir' && argument !== '--name') {
      return { error: 'Unknown arg: ' + argument };
    }
    if (index + 1 >= args.length) {
      return { error: 'Missing value for ' + argument };
    }
    var value = args[index + 1];
    index += 1;
    if (argument === '--project-dir') {
      options.projectDirectory = path.resolve(value);
    } else {
      options.name = value;
    }
  }
  options.projectDirectory = path.resolve(options.projectDirectory);
  return { options: options };
}

function run(adb, args, timeout, environment, binary) {
  return childProcess.spawnSync(adb, args, {
    encoding: binary ? undefined : 'utf8',
    env: environment,
    maxBuffer: 64 * 1024 * 1024,
    timeout: timeout,
    windowsHide: true,
  });
}

function successful(result) {
  return !result.error && result.status === 0;
}

function main(args) {
  var parsed = parseArguments(args);
  if (parsed.error) {
    console.log('SCREENSHOT_STATUS:ERROR');
    console.log(parsed.error);
    return 3;
  }

  var options = parsed.options;
  var environment = Object.assign({}, process.env);
  var adb = resolveAdb(options.projectDirectory, environment, process.platform, os.homedir());
  if (!adb) {
    console.log('SCREENSHOT_STATUS:ERROR');
    console.log('adb not found in the Android SDK or PATH');
    return 3;
  }

  var devicesResult = run(adb, ['devices'], 10000, environment, false);
  var serials = successful(devicesResult) ? emulatorSerials(devicesResult.stdout) : [];
  if (serials.length === 0) {
    console.log('SCREENSHOT_STATUS:NO_BOOTED_DEVICE');
    console.log('boot the emulator first');
    return 1;
  }

  var session = null;
  var sessionFile = path.join(
    options.projectDirectory,
    '.locofy',
    'agent',
    'emulator-session.json',
  );
  if (isFile(sessionFile)) {
    try {
      session = JSON.parse(fs.readFileSync(sessionFile, 'utf8'));
    } catch (_error) {
      // Fall back to the first online emulator when session state is invalid.
    }
  }
  var serial = preferredEmulatorSerial(session, serials);
  var outputDirectory = path.join(options.projectDirectory, '.locofy', 'context');
  fs.mkdirSync(outputDirectory, { recursive: true });
  var output = path.resolve(outputDirectory, sanitizeName(options.name) + '.png');
  var screenshotResult = run(
    adb,
    ['-s', serial, 'exec-out', 'screencap', '-p'],
    60000,
    environment,
    true,
  );
  if (!successful(screenshotResult) || !screenshotResult.stdout) {
    try {
      fs.rmSync(output, { force: true });
    } catch (_error) {
      // Nothing to clean up.
    }
    console.log('SCREENSHOT_STATUS:ERROR');
    console.log('screencap failed');
    return 3;
  }

  fs.writeFileSync(output, screenshotResult.stdout);
  var size = fs.statSync(output).size;
  if (size === 0) {
    fs.rmSync(output, { force: true });
    console.log('SCREENSHOT_STATUS:ERROR');
    console.log('empty screenshot');
    return 3;
  }

  console.log('SCREENSHOT_STATUS:SUCCESS');
  console.log('SCREENSHOT_PATH:' + output);
  console.log('SCREENSHOT_SIZE:' + size + ' bytes');
  return 0;
}

module.exports = {
  emulatorSerials: emulatorSerials,
  preferredEmulatorSerial: preferredEmulatorSerial,
  resolveAdb: resolveAdb,
  sanitizeName: sanitizeName,
  sdkRoots: sdkRoots,
};

if (require.main === module) {
  process.exitCode = main(process.argv.slice(2));
}
